<meta name="viewport" content="width=device-width, initial-scale=1.0">
<style>
*{margin:0;padding:0;box-sizing:border-box}
html,body{background:transparent!important;min-height:0}
body{font-family:'Microsoft YaHei','PingFang SC',sans-serif;padding:0}
:root{--c-size:13.5px}
.mygo-container{border-radius:16px;padding:18px;width:100%;max-width:100%;margin:0;position:relative;overflow:hidden;transition:background 0.4s ease,box-shadow 0.4s ease}
.mygo-container::before{content:'';position:absolute;top:-50%;left:-50%;width:200%;height:200%;animation:pulse 4s ease-in-out infinite;transition:background 0.4s}
@keyframes pulse{0%,100%{transform:scale(1);opacity:0.2}50%{transform:scale(1.1);opacity:0.4}}
.mygo-header{text-align:center;margin-bottom:16px;padding-bottom:12px;position:relative;z-index:1;transition:border-color 0.4s}
.mygo-title{font-size:28px;font-weight:900;letter-spacing:4px;margin-bottom:8px;font-family:'Arial Black',sans-serif;transition:all 0.4s}
.mygo-subtitle{font-size:13px;letter-spacing:2px;opacity:0.85;transition:all 0.4s}
.settings-btn{position:absolute;top:12px;right:12px;width:36px;height:36px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:20px;transition:all 0.3s;z-index:10;border:2px solid}
.settings-btn:hover{transform:rotate(90deg) scale(1.1)}
.settings-panel{position:absolute;top:55px;right:12px;background:rgba(10,20,35,0.98);border-radius:12px;padding:16px;width:240px;display:none;z-index:20;box-shadow:0 8px 24px rgba(0,0,0,0.6);border:2px solid rgba(255,255,255,0.1)}
.settings-panel.active{display:block;animation:slideIn 0.3s ease}
@keyframes slideIn{from{opacity:0;transform:translateY(-10px)}to{opacity:1;transform:translateY(0)}}
.settings-section{margin-bottom:14px}
.settings-section:last-child{margin-bottom:0}
.settings-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}
.settings-label{font-size:13px;font-weight:700;display:block;transition:color 0.4s}
.reset-text{font-size:11px;cursor:pointer;opacity:0.7;text-decoration:underline;border:none;background:none;color:inherit;padding:0}
.reset-text:hover{opacity:1}
.layout-options,.mode-options{display:flex;gap:8px}
.theme-options{display:flex;gap:8px;flex-wrap:wrap;justify-content:center}
.option-btn{flex:1;padding:8px 6px;background:rgba(255,255,255,0.1);border:2px solid rgba(255,255,255,0.2);border-radius:8px;color:#e8f4f8;font-size:12px;cursor:pointer;transition:all 0.25s;text-align:center}
.option-btn:hover{background:rgba(255,255,255,0.2)}
.option-btn.active{background:rgba(255,255,255,0.25);border-color:rgba(255,215,0,0.6);box-shadow:0 0 12px rgba(255,215,0,0.3)}
.theme-btn{width:36px;height:36px;border-radius:50%;cursor:pointer;transition:all 0.25s;position:relative;border:3px solid rgba(255,255,255,0.4)}
.theme-btn:hover{transform:scale(1.2)}
.theme-btn.active{border-width:4px;border-color:#fff;box-shadow:0 0 20px currentColor,inset 0 0 10px rgba(255,255,255,0.3)}
.theme-btn.cyber{background:linear-gradient(135deg,#00f5ff,#0077b6,#00d4ff)}
.theme-btn.mystic{background:linear-gradient(135deg,#ff6fd8,#9d4edd,#3c096c)}
.theme-btn.forest{background:linear-gradient(135deg,#95d5b2,#2d6a4f,#1b4332)}
.theme-btn.royal{background:linear-gradient(135deg,#ffd700,#b8860b,#8b4513)}
.theme-btn.mono{background:linear-gradient(135deg,#ffffff,#888888,#000000)}
.theme-btn.sakura{background:linear-gradient(135deg,#ffc0cb,#ffb7b2,#ff9a9e)}
.theme-btn.sunset{background:linear-gradient(135deg,#ff9966,#ff5e62,#ff0000)}
.theme-btn.crimson{background:linear-gradient(135deg,#800000,#4a0000,#000000)}
.range-input{width:100%;height:6px;background:rgba(255,255,255,0.2);border-radius:4px;outline:none;-webkit-appearance:none;cursor:pointer}
.range-input::-webkit-slider-thumb{-webkit-appearance:none;width:16px;height:16px;background:#fff;border-radius:50%;cursor:pointer;transition:all 0.2s}
.range-input::-webkit-slider-thumb:hover{transform:scale(1.2)}
.color-input{width:100%;height:30px;border:none;background:transparent;cursor:pointer;padding:0}
.choice-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;position:relative;z-index:1;transition:all 0.3s ease}
.choice-grid.vertical{grid-template-columns:1fr;gap:12px}
.choice-btn{width:100%;border-radius:14px;padding:16px 14px;cursor:pointer;transition:all 0.35s cubic-bezier(0.4,0,0.2,1);text-align:left;position:relative;overflow:hidden;height:100%;display:flex;flex-direction:column;border:2px solid}
.choice-btn::before{content:'';position:absolute;top:0;left:-100%;width:100%;height:100%;transition:left 0.7s ease}
.choice-btn::after{content:'';position:absolute;top:0;left:0;width:100%;height:100%;opacity:0;transition:opacity 0.3s}
.choice-btn:hover::before{left:100%}
.choice-btn:hover::after{opacity:1}
.choice-btn:hover{transform:scale(1.04) translateY(-3px)}
.choice-btn:active{transform:scale(0.98) translateY(0)}
.choice-head{display:flex;align-items:center;justify-content:center;gap:8px;margin-bottom:10px;padding-bottom:8px;border-bottom:1px dashed;transition:border-color 0.4s}
.choice-emoji{font-size:24px;animation:float 3s ease-in-out infinite;transition:filter 0.4s}
@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
.choice-num{font-weight:900;font-size:16px;letter-spacing:1px;transition:all 0.4s;color:var(--c-color)}
.choice-text{color:var(--c-color);font-size:var(--c-size);line-height:1.55;overflow:hidden;display:-webkit-box;-webkit-line-clamp:6;-webkit-box-orient:vertical;text-align:justify;text-shadow:0 1px 3px rgba(0,0,0,0.6);transition:color 0.4s ease,text-shadow 0.4s ease}
.mygo-footer{text-align:center;margin-top:14px;padding-top:12px;font-size:12px;opacity:0.8;letter-spacing:2px;position:relative;z-index:1;transition:all 0.4s}

.theme-cyber{--c-color:#e8f4f8;background:linear-gradient(135deg,#0a1628 0%,#0d2847 30%,#1a3a5c 60%,#0a1f3d 100%);box-shadow:0 4px 20px rgba(0,212,255,0.25),0 0 40px rgba(0,180,216,0.1),inset 0 1px 0 rgba(0,212,255,0.1)}
.theme-cyber::before{background:radial-gradient(ellipse at 30% 20%,rgba(0,245,255,0.15) 0%,transparent 50%),radial-gradient(ellipse at 70% 80%,rgba(0,119,182,0.1) 0%,transparent 50%)}
.theme-cyber .mygo-header{border-bottom:2px solid rgba(0,212,255,0.25)}
.theme-cyber .mygo-title{color:#00f5ff;text-shadow:0 0 10px rgba(0,245,255,0.8),0 0 30px rgba(0,212,255,0.4)}
.theme-cyber .mygo-subtitle{color:#7df9ff}
.theme-cyber .settings-btn{background:rgba(0,212,255,0.15);border-color:rgba(0,212,255,0.3)}
.theme-cyber .settings-btn:hover{background:rgba(0,212,255,0.3);border-color:#00f5ff;box-shadow:0 0 15px rgba(0,245,255,0.5)}
.theme-cyber .settings-label{color:#00f5ff}
.theme-cyber .choice-btn{background:linear-gradient(145deg,rgba(0,30,60,0.8),rgba(0,50,80,0.6));border-color:rgba(0,212,255,0.2);box-shadow:0 4px 15px rgba(0,0,0,0.4),inset 0 1px 0 rgba(0,212,255,0.1)}
.theme-cyber .choice-btn::before{background:linear-gradient(90deg,transparent,rgba(0,245,255,0.3),transparent)}
.theme-cyber .choice-btn::after{background:radial-gradient(circle at center,rgba(0,245,255,0.15),transparent)}
.theme-cyber .choice-btn:hover{border-color:rgba(0,245,255,0.5);box-shadow:0 8px 30px rgba(0,212,255,0.4),0 0 20px rgba(0,245,255,0.2)}
.theme-cyber .choice-head{border-color:rgba(0,212,255,0.2)}
.theme-cyber .choice-num{text-shadow:0 0 10px rgba(0,245,255,0.7)}
.theme-cyber .mygo-footer{color:#00f5ff;border-top:2px solid rgba(0,212,255,0.25)}

.theme-mystic{--c-color:#e8f4f8;background:linear-gradient(135deg,#1a0a2e 0%,#2d1b4e 30%,#4a1942 60%,#16082a 100%);box-shadow:0 4px 20px rgba(157,78,221,0.25),0 0 40px rgba(255,111,216,0.1),inset 0 1px 0 rgba(255,111,216,0.1)}
.theme-mystic::before{background:radial-gradient(ellipse at 20% 30%,rgba(255,111,216,0.12) 0%,transparent 50%),radial-gradient(ellipse at 80% 70%,rgba(157,78,221,0.1) 0%,transparent 50%)}
.theme-mystic .mygo-header{border-bottom:2px solid rgba(255,111,216,0.25)}
.theme-mystic .mygo-title{color:#ff6fd8;text-shadow:0 0 10px rgba(255,111,216,0.8),0 0 30px rgba(157,78,221,0.5)}
.theme-mystic .mygo-subtitle{color:#e0aaff}
.theme-mystic .settings-btn{background:rgba(157,78,221,0.15);border-color:rgba(255,111,216,0.3)}
.theme-mystic .settings-btn:hover{background:rgba(157,78,221,0.3);border-color:#ff6fd8;box-shadow:0 0 15px rgba(255,111,216,0.5)}
.theme-mystic .settings-label{color:#ff6fd8}
.theme-mystic .choice-btn{background:linear-gradient(145deg,rgba(45,27,78,0.8),rgba(74,25,66,0.6));border-color:rgba(255,111,216,0.2);box-shadow:0 4px 15px rgba(0,0,0,0.4),inset 0 1px 0 rgba(255,111,216,0.1)}
.theme-mystic .choice-btn::before{background:linear-gradient(90deg,transparent,rgba(255,111,216,0.3),transparent)}
.theme-mystic .choice-btn::after{background:radial-gradient(circle at center,rgba(224,170,255,0.15),transparent)}
.theme-mystic .choice-btn:hover{border-color:rgba(255,111,216,0.5);box-shadow:0 8px 30px rgba(157,78,221,0.4),0 0 20px rgba(255,111,216,0.2)}
.theme-mystic .choice-head{border-color:rgba(255,111,216,0.2)}
.theme-mystic .choice-num{text-shadow:0 0 10px rgba(255,111,216,0.7)}
.theme-mystic .mygo-footer{color:#ff6fd8;border-top:2px solid rgba(255,111,216,0.25)}

.theme-forest{--c-color:#e8f4f8;background:linear-gradient(135deg,#0d1f12 0%,#1b4332 30%,#2d6a4f 60%,#0a1a10 100%);box-shadow:0 4px 20px rgba(82,183,136,0.2),0 0 40px rgba(45,106,79,0.1),inset 0 1px 0 rgba(149,213,178,0.1)}
.theme-forest::before{background:radial-gradient(ellipse at 25% 25%,rgba(149,213,178,0.1) 0%,transparent 50%),radial-gradient(ellipse at 75% 75%,rgba(45,106,79,0.08) 0%,transparent 50%)}
.theme-forest .mygo-header{border-bottom:2px solid rgba(149,213,178,0.25)}
.theme-forest .mygo-title{color:#95d5b2;text-shadow:0 0 10px rgba(149,213,178,0.7),0 0 30px rgba(82,183,136,0.4)}
.theme-forest .mygo-subtitle{color:#b7e4c7}
.theme-forest .settings-btn{background:rgba(45,106,79,0.2);border-color:rgba(149,213,178,0.3)}
.theme-forest .settings-btn:hover{background:rgba(45,106,79,0.4);border-color:#95d5b2;box-shadow:0 0 15px rgba(149,213,178,0.5)}
.theme-forest .settings-label{color:#95d5b2}
.theme-forest .choice-btn{background:linear-gradient(145deg,rgba(27,67,50,0.8),rgba(45,106,79,0.5));border-color:rgba(149,213,178,0.2);box-shadow:0 4px 15px rgba(0,0,0,0.4),inset 0 1px 0 rgba(149,213,178,0.1)}
.theme-forest .choice-btn::before{background:linear-gradient(90deg,transparent,rgba(149,213,178,0.25),transparent)}
.theme-forest .choice-btn::after{background:radial-gradient(circle at center,rgba(183,228,199,0.12),transparent)}
.theme-forest .choice-btn:hover{border-color:rgba(149,213,178,0.5);box-shadow:0 8px 30px rgba(45,106,79,0.4),0 0 20px rgba(149,213,178,0.2)}
.theme-forest .choice-head{border-color:rgba(149,213,178,0.2)}
.theme-forest .choice-num{text-shadow:0 0 10px rgba(149,213,178,0.6)}
.theme-forest .mygo-footer{color:#95d5b2;border-top:2px solid rgba(149,213,178,0.25)}

.theme-royal{--c-color:#e8f4f8;background:linear-gradient(135deg,#1a1005 0%,#3d2810 30%,#5c3d1a 60%,#1f1408 100%);box-shadow:0 4px 20px rgba(255,215,0,0.2),0 0 40px rgba(184,134,11,0.1),inset 0 1px 0 rgba(255,215,0,0.15)}
.theme-royal::before{background:radial-gradient(ellipse at 30% 20%,rgba(255,215,0,0.1) 0%,transparent 50%),radial-gradient(ellipse at 70% 80%,rgba(184,134,11,0.08) 0%,transparent 50%)}
.theme-royal .mygo-header{border-bottom:2px solid rgba(255,215,0,0.3)}
.theme-royal .mygo-title{color:#ffd700;text-shadow:0 0 10px rgba(255,215,0,0.8),0 0 30px rgba(184,134,11,0.5)}
.theme-royal .mygo-subtitle{color:#ffe066}
.theme-royal .settings-btn{background:rgba(184,134,11,0.2);border-color:rgba(255,215,0,0.3)}
.theme-royal .settings-btn:hover{background:rgba(184,134,11,0.4);border-color:#ffd700;box-shadow:0 0 15px rgba(255,215,0,0.5)}
.theme-royal .settings-label{color:#ffd700}
.theme-royal .choice-btn{background:linear-gradient(145deg,rgba(61,40,16,0.8),rgba(92,61,26,0.6));border-color:rgba(255,215,0,0.2);box-shadow:0 4px 15px rgba(0,0,0,0.4),inset 0 1px 0 rgba(255,215,0,0.15)}
.theme-royal .choice-btn::before{background:linear-gradient(90deg,transparent,rgba(255,215,0,0.3),transparent)}
.theme-royal .choice-btn::after{background:radial-gradient(circle at center,rgba(255,224,102,0.12),transparent)}
.theme-royal .choice-btn:hover{border-color:rgba(255,215,0,0.5);box-shadow:0 8px 30px rgba(184,134,11,0.4),0 0 20px rgba(255,215,0,0.25)}
.theme-royal .choice-head{border-color:rgba(255,215,0,0.25)}
.theme-royal .choice-num{text-shadow:0 0 10px rgba(255,215,0,0.7)}
.theme-royal .mygo-footer{color:#ffd700;border-top:2px solid rgba(255,215,0,0.3)}

.theme-mono{--c-color:#dddddd;background:linear-gradient(135deg,#000 0%,#1a1a1a 100%);box-shadow:0 4px 20px rgba(255,255,255,0.15),0 0 40px rgba(255,255,255,0.05)}
.theme-mono::before{background:radial-gradient(ellipse at 50% 50%,rgba(255,255,255,0.05) 0%,transparent 60%)}
.theme-mono .mygo-header{border-bottom:2px solid rgba(255,255,255,0.3)}
.theme-mono .mygo-title{color:#fff;text-shadow:0 0 10px rgba(255,255,255,0.4)}
.theme-mono .mygo-subtitle{color:#ccc}
.theme-mono .settings-btn{background:rgba(255,255,255,0.1);border-color:rgba(255,255,255,0.4);color:#fff}
.theme-mono .settings-btn:hover{background:#fff;color:#000;box-shadow:0 0 15px rgba(255,255,255,0.5)}
.theme-mono .settings-label{color:#fff}
.theme-mono .choice-btn{background:linear-gradient(145deg,#111,#222);border-color:rgba(255,255,255,0.3);box-shadow:0 4px 15px rgba(0,0,0,0.6)}
.theme-mono .choice-btn::before{background:linear-gradient(90deg,transparent,rgba(255,255,255,0.2),transparent)}
.theme-mono .choice-btn::after{background:radial-gradient(circle at center,rgba(255,255,255,0.1),transparent)}
.theme-mono .choice-btn:hover{border-color:#fff;box-shadow:0 8px 30px rgba(255,255,255,0.2)}
.theme-mono .choice-head{border-color:rgba(255,255,255,0.3)}
.theme-mono .choice-num{text-shadow:none;}
.theme-mono .choice-text{text-shadow:none}
.theme-mono .mygo-footer{color:#aaa;border-top:2px solid rgba(255,255,255,0.3)}

.theme-sakura{--c-color:#8b4563;background:linear-gradient(135deg,#fff0f5 0%,#ffe4e1 50%,#ffc0cb 100%);box-shadow:0 4px 20px rgba(255,105,180,0.25),0 0 40px rgba(255,182,193,0.3)}
.theme-sakura::before{background:radial-gradient(ellipse at 30% 20%,rgba(255,255,255,0.8) 0%,transparent 60%),radial-gradient(ellipse at 80% 80%,rgba(255,182,193,0.4) 0%,transparent 50%)}
.theme-sakura .mygo-header{border-bottom:2px solid rgba(219,112,147,0.3)}
.theme-sakura .mygo-title{color:#d87093;text-shadow:2px 2px 4px rgba(255,255,255,0.8),0 0 15px rgba(255,105,180,0.3)}
.theme-sakura .mygo-subtitle{color:#db7093;text-shadow:1px 1px 2px #fff}
.theme-sakura .settings-btn{background:rgba(255,255,255,0.4);border-color:rgba(219,112,147,0.4);color:#d87093}
.theme-sakura .settings-btn:hover{background:#fff;border-color:#ff69b4;color:#ff1493;box-shadow:0 0 15px rgba(255,182,193,0.8)}
.theme-sakura .settings-panel{background:rgba(255,240,245,0.95);border-color:rgba(255,182,193,0.5);box-shadow:0 8px 24px rgba(219,112,147,0.2)}
.theme-sakura .settings-label{color:#d87093}
.theme-sakura .option-btn{background:rgba(219,112,147,0.1);border-color:rgba(219,112,147,0.3);color:#c71585}
.theme-sakura .option-btn.active{background:rgba(255,255,255,0.6);border-color:#ff69b4}
.theme-sakura .choice-btn{background:linear-gradient(145deg,rgba(255,255,255,0.7),rgba(255,240,245,0.6));border-color:rgba(255,182,193,0.6);box-shadow:0 4px 15px rgba(219,112,147,0.1)}
.theme-sakura .choice-btn::before{background:linear-gradient(90deg,transparent,rgba(255,192,203,0.4),transparent)}
.theme-sakura .choice-btn::after{background:radial-gradient(circle at center,rgba(255,20,147,0.05),transparent)}
.theme-sakura .choice-btn:hover{border-color:#ff69b4;box-shadow:0 8px 25px rgba(219,112,147,0.25);transform:scale(1.03) translateY(-3px)}
.theme-sakura .choice-head{border-color:rgba(219,112,147,0.3)}
.theme-sakura .choice-num{text-shadow:1px 1px 0 #fff}
.theme-sakura .choice-text{text-shadow:none}
.theme-sakura .mygo-footer{color:#d87093;border-top:2px solid rgba(219,112,147,0.3);text-shadow:1px 1px 0 #fff}

.theme-sunset{--c-color:#fff5ee;background:linear-gradient(135deg,#2c3e50 0%,#fd746c 100%);box-shadow:0 4px 20px rgba(253,116,108,0.3),inset 0 1px 0 rgba(255,255,255,0.1)}
.theme-sunset .mygo-header{border-bottom:2px solid rgba(255,160,122,0.3)}
.theme-sunset .mygo-title{color:#ffdab9;text-shadow:0 0 10px rgba(255,69,0,0.5)}
.theme-sunset .mygo-subtitle{color:#ffd700}
.theme-sunset .settings-btn{background:rgba(255,255,255,0.1);border-color:rgba(255,160,122,0.4);color:#ffdab9}
.theme-sunset .settings-btn:hover{background:rgba(255,69,0,0.2);border-color:#ffa07a;box-shadow:0 0 15px rgba(255,69,0,0.4)}
.theme-sunset .settings-label{color:#ffdab9}
.theme-sunset .choice-btn{background:linear-gradient(145deg,rgba(44,62,80,0.8),rgba(253,116,108,0.4));border-color:rgba(255,160,122,0.3);box-shadow:0 4px 15px rgba(0,0,0,0.3)}
.theme-sunset .choice-btn:hover{border-color:#ffdab9;box-shadow:0 8px 30px rgba(253,116,108,0.4)}
.theme-sunset .choice-head{border-color:rgba(255,160,122,0.3)}
.theme-sunset .choice-num{text-shadow:0 0 5px rgba(255,69,0,0.5)}
.theme-sunset .mygo-footer{color:#ffdab9;border-top:2px solid rgba(255,160,122,0.3)}

.theme-crimson{--c-color:#ffe6e6;background:linear-gradient(135deg,#000000 0%,#430000 50%,#1a0000 100%);box-shadow:0 4px 20px rgba(255,0,0,0.2),inset 0 1px 0 rgba(255,0,0,0.1)}
.theme-crimson::before{background:radial-gradient(ellipse at 50% 0%,rgba(255,0,0,0.15) 0%,transparent 60%)}
.theme-crimson .mygo-header{border-bottom:2px solid rgba(139,0,0,0.5)}
.theme-crimson .mygo-title{color:#ff3333;text-shadow:0 0 20px rgba(139,0,0,0.8)}
.theme-crimson .mygo-subtitle{color:#cc0000}
.theme-crimson .settings-btn{background:rgba(60,0,0,0.5);border-color:rgba(255,0,0,0.3);color:#ff0000}
.theme-crimson .settings-btn:hover{background:rgba(255,0,0,0.2);border-color:#ff0000;box-shadow:0 0 20px rgba(255,0,0,0.6)}
.theme-crimson .settings-label{color:#ff3333}
.theme-crimson .choice-btn{background:linear-gradient(145deg,rgba(20,0,0,0.9),rgba(50,0,0,0.7));border-color:rgba(139,0,0,0.5);box-shadow:0 4px 15px rgba(0,0,0,0.8)}
.theme-crimson .choice-btn:hover{border-color:#ff0000;box-shadow:0 8px 30px rgba(139,0,0,0.6)}
.theme-crimson .choice-head{border-color:rgba(139,0,0,0.5)}
.theme-crimson .choice-num{text-shadow:0 0 10px rgba(255,0,0,0.5)}
.theme-crimson .mygo-footer{color:#cc0000;border-top:2px solid rgba(139,0,0,0.5)}

@media (max-width:768px){.mygo-container{padding:16px;border-radius:14px}.mygo-title{font-size:26px}.choice-grid{gap:12px}.choice-btn{padding:14px 12px}.choice-emoji{font-size:22px}.choice-num{font-size:15px}.choice-text{font-size:calc(var(--c-size) - 1px)}.settings-panel{width:220px;right:8px;top:50px}}
